# EPISODE 011 — Jazz Aviation flight 646 (Air Canada Express 8646), CRJ-900 C-GNJZ, collision with ARFF vehicle Rescue 35 on runway 4, LaGuardia (LGA), March 22, 2026, 23:37 EDT.
# NTSB DCA26MA161 — investigation ONGOING (no probable cause). Sources: NTSB preliminary report (Apr 2026), NTSB investigation page, NTSB media briefings Mar 23-24 2026 + B-roll (NTSBgov YouTube),
# FAA press release May 13 2026 (vehicle transponders). Cause/blame: NEVER stated. No names of crew, controllers, ARFF personnel, victims.
# (id, spoken text, pause_after, speed, visual)  visual = ("3d", shot) | ("card", name) | ("photo", file, credit) | ("clip", file, start_s, label)
B1 = "NTSB MEDIA BRIEFING 1 · MARCH 23, 2026"
B2 = "NTSB MEDIA BRIEFING 2 · MARCH 24, 2026"
BR = "NTSB B-ROLL · INVESTIGATORS DOCUMENT THE SCENE"
P1 = "NTSB PRELIMINARY REPORT · FIG. 1 · THE VEHICLES' PLANNED ROUTE (GOOGLE EARTH)"
P2 = "NTSB PRELIMINARY REPORT · FIG. 2 · POSITIONS AT 23:37:04"
P3 = "NTSB PRELIMINARY REPORT · FIG. 3 · THE AIRPLANE AND TRUCK 1 AFTER THE COLLISION"
P4 = "NTSB PRELIMINARY REPORT · FIG. 4 · THE AIRPLANE, LEFT SIDE"
P5 = "NTSB PRELIMINARY REPORT · FIG. 5 · TRUCK 1 (RESCUE 35)"
P6 = "NTSB PRELIMINARY REPORT · FIG. 6 · THE TOWER, GROUND CONTROL POSITION, LOOKING AT TAXIWAY D"
