LINES = [
 # ---- cold open (3D from NTSB numbers)
 ("o1", "Sunday, March twenty-second, two thousand twenty-six. Eleven thirty-seven at night, LaGuardia Airport, New York.", 0.8, 1.0, ("3d", "open")),
 ("o2", "Jazz Aviation flight six forty-six, flying as Air Canada flight eighty-six forty-six, a C R J nine hundred from Montreal, is landing on runway four. Seventy-six people are on board.", 0.8, 1.0, ("3d", "open")),
 ("o3", "On taxiway D, the tower has just instructed a rescue truck to cross that runway.", 0.72, 1.0, ("3d", "open")),
 ("o4", "At that moment the jet is about a quarter mile out on final approach, about a hundred and thirty feet up. About twenty seconds later, the two collide.", 0.8, 1.0, ("3d", "open")),
 ("o5", "Both pilots were fatally injured. Thirty-nine people were taken to hospitals, with six serious injuries reported.", 0.56, 1.0, ("clip", "relay/br1.mp4", 6.0, BR)),
 ("o6", "This is the N T S B's preliminary report, moment by moment: the radio calls, the vehicles, the red lights, and a surface radar that generated no alert in the tower.", 0.88, 1.0, ("clip", "relay/br1.mp4", 40.0, BR)),
 ("t1", "Jazz flight six forty-six, LaGuardia.", 1.12, 0.95, ("card", "title")),
 # ---- ground rules
 ("h1", "A few rules for this video. The investigation is not finished. The N T S B has not determined a probable cause, and neither will we. Everything here comes from the N T S B's preliminary report, its investigation page and its briefings, plus one F A A announcement, which we will flag when it comes up.", 0.88, 1.0, ("clip", "relay/m1a.mp4", 10.0, B1)),
 ("h2", "We do not name the pilots, the controllers, or the firefighters. When the report quotes a radio call, we quote the report. And where it does not say why something happened, we say so.", 0.88, 1.0, ("card", "how")),
 ("h3", "The three D scenes are built from the report's own numbers. Between those points, the motion is interpolated. The aircraft model is generic, and the truck is an illustration.", 0.88, 1.0, ("3d", "top")),
 # ---- the flight
 ("a1", "The flight. Jazz Aviation operated it, doing business as Air Canada flight eighty-six forty-six. The airplane was an M H I R J Aviation, formerly Bombardier, C L six hundred two D twenty-four, a C R J nine hundred, registered C G N J Z. It was on a scheduled trip from Montreal to LaGuardia, flown under the rules for foreign air carriers.", 0.88, 1.0, ("photo", "ph/fig4.png", P4)),
 ("a2", "Aboard were two pilots, two flight attendants, and seventy-two passengers. In total, the report lists two fatal injuries, six serious, and thirty-three minor.", 0.88, 1.0, ("clip", "relay/m1b.mp4", 20.0, B1)),
 ("a3", "The pilots had flown three legs that day: Montreal to Quebec City, back to Montreal, and then this one, the last of the day. It was the first day of a four-day trip. The captain had about thirty-six hundred flight hours, and had been a captain since the end of December. The first officer had about seven hundred hours. They had flown together once before. The report gives these figures without comment. It gives experience figures for the controllers and the firefighters too.", 1.12, 1.0, ("card", "crew")),
 # ---- the investigation
 ("i1", "The N T S B traveled to the scene, and invited parties to take part: the F A A, the National Air Traffic Controllers Association, the Port Authority of New York and New Jersey, the Sergeants Benevolent Association, and the Police Benevolent Association.", 0.88, 1.0, ("clip", "relay/m1c.mp4", 10.0, B1)),
 ("i2", "Because the airplane was built and operated by Canadian companies, Canada's Transportation Safety Board is part of the investigation. Transport Canada, the manufacturer, Jazz Aviation, the Air Line Pilots Association and the Canadian Flight Attendant Union are technical advisors to the Canadian representative.", 0.88, 1.0, ("clip", "relay/m1d.mp4", 10.0, B1)),
 ("i3", "The investigators were split into groups: air carrier operations, structures, systems and powerplants, air traffic control, and airport operations, firefighting and survival factors. Human performance is part of three of them.", 0.88, 1.0, ("clip", "relay/m2a.mp4", 10.0, B2)),
 ("i4", "Both recorders were recovered, the cockpit voice recorder and the flight data recorder, along with the airplane's quick access recorder, and all three were downloaded at the board's laboratory in Washington. The truck's own data recorder, engine control module and situational display were kept for download later.", 0.88, 1.0, ("clip", "relay/br2.mp4", 8.0, BR)),
 ("i5", "At two briefings, on March twenty-third and twenty-fourth, board investigators described the first days of the work. What follows is the preliminary report, updated in April.", 1.12, 1.0, ("clip", "relay/m2b.mp4", 10.0, B2)),
 # ---- weather
 ("w1", "The weather. Night, visual conditions, light rain. The last automated observation before the accident, at ten fifty-one, about forty-six minutes earlier, showed visibility seven miles in light rain, scattered clouds at six thousand feet, and an overcast at nine thousand five hundred. The wind was seven knots, from zero seven three degrees.", 0.88, 1.0, ("clip", "relay/m1g.mp4", 20.0, B1)),
 ("w2", "The runway was considered wet or contaminated for landing purposes. The airport information broadcast in effect at the time reported good braking action along the whole of runway four.", 1.12, 1.0, ("clip", "relay/m2c.mp4", 10.0, B2)),
 # ---- the emergency elsewhere
 ("e1", "To understand the runway, start at terminal B. Earlier, an airplane had performed two rejected takeoffs, followed by a ground emergency at terminal B. The emergency was declared at eleven thirty-one and forty-two seconds.", 0.88, 1.0, ("photo", "ph/fig1.png", P1)),
 ("e2", "Six rescue and firefighting vehicles, four trucks, a tool truck and an airstair truck, and one Port Authority police vehicle, were responding. Their route would take them across runway four.", 0.88, 1.0, ("photo", "ph/fig1.png", P1)),
 ("e3", "Two controllers were on duty in the tower, which the report says was consistent with the mid-shift schedule. Both were qualified and current on every position. The local controller, who handles the runways, had about eighteen years of experience and had been on position about forty-two minutes. The ground controller, who was also the controller in charge, had about nineteen years, and about fifty-one minutes on position.", 0.88, 1.0, ("clip", "relay/br1.mp4", 60.0, BR)),
 ("e4", "While the ground controller coordinated the emergency, the local controller took over transmitting instructions on both the ground and the local frequencies.", 1.12, 1.0, ("photo", "ph/fig6.png", P6)),
 # ---- the minute, step by step
 ("l1", "Eleven thirty-five and seven seconds. The local controller clears the jet to land on runway four. It is on a five-mile final, at about nineteen hundred feet.", 0.8, 1.0, ("3d", "tl_wide")),
 ("l2", "Twenty-one seconds later, the rescue truck, called Rescue thirty-five, leaves the fire station along with the other six vehicles. The jet is four point six nautical miles from taxiway D, at about fifteen hundred feet.", 0.8, 1.0, ("3d", "tl_wide")),
 ("l3", "The vehicles gather near the intersection of taxiways B B and D. Their intended path: continue along taxiway D, cross runway four, and proceed to a destination on the other side, marked in the report's figure.", 0.88, 1.0, ("photo", "ph/fig1.png", P1)),
 ("l4", "Eleven thirty-five forty-seven. The tool truck, called Truck seven, which was planned to be the lead vehicle, tries to call the tower. A simultaneous radio transmission on the same frequency obscures the call. The jet is three point seven nautical miles from taxiway D, at eleven hundred eighty feet.", 0.8, 1.0, ("3d", "tl_wide")),
 ("l5", "Eleven thirty-six twenty-one. Truck seven tries again. Before the tower responds, Truck seven coordinates with the rescue truck, call sign Truck one, to contact the tower. The jet is two point three nautical miles from taxiway D, at about six hundred fifty feet.", 0.8, 1.0, ("3d", "tl_wide")),
 ("l6", "Eleven thirty-six forty-four. The local controller asks which vehicle needs to cross a runway. At the same time, Truck one moves to the front of the waiting vehicles. The jet is one point five nautical miles from taxiway D, at four hundred feet.", 0.8, 1.0, ("3d", "tl_wide")),
 ("l7", "Seven seconds later, the red runway entrance lights come on at the intersection of runway four and taxiway D. Truck one is stopped on taxiway D, about four hundred sixty feet from the runway edge. The jet is one point two nautical miles from taxiway D, at two hundred eighty-seven feet.", 0.8, 1.0, ("3d", "tl_close")),
 ("l8", "Eleven thirty-six fifty-six. Truck one's crew replies, Truck one and company, and the tower acknowledges. Truck one then requests to cross runway four at taxiway D, and the tower instructs them to cross. That is eleven thirty-seven and four seconds.", 0.8, 1.0, ("3d", "tl_close")),
 ("l9", "At that moment the jet is about a hundred and thirty feet above the ground, about a quarter mile out on final approach, which the report puts at about forty-four hundred feet from taxiway D.", 0.88, 1.0, ("photo", "ph/fig2.png", P2)),
 ("l10", "Eleven thirty-seven oh seven. Truck one reads back the clearance and starts moving along taxiway D toward the runway. The jet is thirty-seven hundred feet from taxiway D, at eighty-seven feet.", 0.8, 1.0, ("3d", "tl_close")),
 ("l11", "At eleven thirty-seven eleven the jet crosses the runway threshold. Truck one is traveling at ten knots, about eleven and a half miles an hour, and is about four hundred ten feet from the runway edge.", 0.8, 1.0, ("3d", "tl_close")),
 ("l12", "One second later, the tower gives a taxi instruction to another airplane, and immediately afterward tells Truck one to stop. The truck is crossing taxiway A A. Its speed keeps increasing. The jet is twenty-five hundred fifty feet from taxiway D, at thirty feet, at one hundred thirty-three knots.", 0.8, 1.0, ("3d", "tl_close")),
 ("l13", "Eleven thirty-seven seventeen. The jet's main wheels touch down, about fourteen hundred fifty feet from taxiway D, at one hundred twenty-eight knots. Control passes from the first officer to the captain. Truck one is crossing the hold short line at about twenty-four miles an hour.", 0.8, 1.0, ("3d", "tl_close")),
 ("l14", "Three seconds later, the tower tells Truck one to stop again. The jet's brakes come on and the thrust reversers deploy. Truck one is a little over a hundred feet from the runway, at about twenty-nine miles an hour.", 0.8, 1.0, ("3d", "tl_close")),
 ("l15", "The red lights go off at eleven thirty-seven twenty-one. A second later, the jet's nose wheel touches down, four hundred feet from taxiway D, at one hundred six knots. The truck, at thirty miles an hour, is just entering the runway.", 0.8, 1.0, ("3d", "tl_close")),
 ("l16", "The truck turns left just before the collision. The jet's rudder moves about six degrees to the left. The last recorded groundspeed, before the data ends: ninety knots, one hundred four miles an hour.", 0.96, 1.0, ("3d", "tl_close")),
 # ---- after
 ("x1", "The collision happened at the intersection of taxiway D and runway four. The jet came to rest next to taxiway B, between taxiways D and E, upright, initially nose down because of the crush damage. Truck one came to rest just northwest of it, on its left side.", 0.88, 1.0, ("photo", "ph/fig3.png", P3)),
 ("x2", "The debris path was about three hundred feet long. Investigators documented it with drones, G P S and photographs, and scanned the airplane and the truck with a three D laser system.", 0.88, 1.0, ("clip", "relay/br2.mp4", 40.0, BR)),
 ("x3", "Passengers got out on their own, through the four overwing exits. The vehicles that had been heading to the terminal B emergency turned to the airplane, and firefighters helped with the evacuation. During it, the airplane tilted nose up until its tail touched the ground.", 0.88, 1.0, ("clip", "relay/br2.mp4", 28.0, BR)),
 ("x4", "On the airplane, the worst damage was forward of the first row of passenger seats. The two pilot seats, an unoccupied flight deck observer seat and the forward flight attendant seat came loose from the airplane. The passenger seats stayed attached, most with minor or no damage.", 0.88, 1.0, ("clip", "relay/br3.mp4", 0.0, BR)),
 ("x5", "The airplane examination found no anomalies with the pitch, roll or yaw flight control surfaces. Slats and flaps were fully extended. The spoilers were retracted, but flight data show the ground spoilers activated about six seconds before the data ended. Both thrust reversers were fully deployed.", 0.88, 1.0, ("photo", "ph/fig4.png", P4)),
 ("x6", "The truck's right side was substantially damaged. Its fifteen hundred gallon water tank broke apart, and its foam tank was breached. The cab was largely undamaged.", 0.88, 1.0, ("photo", "ph/fig5.png", P5)),
 # ---- interviews
 ("v1", "The report includes interviews. The driver of Truck seven heard the tower clear Truck one to cross. A moment later, the driver saw the airplane, and announced, stop, stop, stop, on the radio. The report says there are no recordings of the firefighters' own radio channel.", 0.88, 1.0, ("clip", "relay/m2d.mp4", 10.0, B2)),
 ("v2", "The turret operator in Truck one remembered hearing the words stop, stop, stop on the tower frequency, but did not know who it was meant for. Then came, Truck one, stop, stop, stop, and the operator realized it was for them, and noticed that they had entered the runway. As the truck turned left, the operator saw the airplane's lights.", 0.88, 1.0, ("clip", "relay/m2e.mp4", 10.0, B2)),
 ("v3", "The flight attendant seated at the back described a normal flight until an impact. The flight attendant tried to call the pilots and got no answer. It was dark, the report says, and passengers left in an orderly way, through all exits.", 1.12, 1.0, ("clip", "relay/br3.mp4", 50.0, BR)),
 # ---- technology
 ("r1", "Now the technology. The airport was equipped with a surface surveillance system called A S D E X. It fuses surface radar, multilateration, ADS-B and transponder signals into a display in the tower, so controllers can see aircraft and vehicles on the ground, even in poor visibility. It is designed to alert controllers to potential runway conflicts.", 0.88, 1.0, ("clip", "relay/br2.mp4", 22.0, BR)),
 ("r2", "The F A A reviewed the system's data. It did not generate an alert in the tower, aural or visual, about the potential runway conflict.", 0.88, 1.0, ("photo", "ph/fig7.png", P7)),
 ("r3", "The report describes why. The vehicles in the group had no transponders. They were close together, so their radar targets kept merging and separating, and the system could not establish confident tracks. At the time of the accident, the tower display showed two radar targets on taxiway D, not seven vehicles.", 0.88, 1.0, ("photo", "ph/fig7.png", P7)),
 ("r4", "Without transponders, the system could not tell the vehicles apart or reliably place them, so it could not match the jet's track with the truck's. It did not predict a conflict.", 0.88, 1.0, ("clip", "relay/m1e.mp4", 10.0, B1)),
 ("r6", "A second system: runway status lights. LaGuardia is one of twenty airports that have it. At taxiway crossings, red runway entrance lights run along the taxiway centerline, from the hold short line to the runway edge. When an airplane is landing or taking off, the system turns them red automatically, to warn anyone about to cross.", 0.88, 1.0, ("photo", "ph/fig8.png", P8)),
 ("r7", "After touchdown they go dark, one intersection at a time. The system is designed to turn each set off two to three seconds before the airplane reaches it.", 0.88, 1.0, ("card", "rels")),
 ("r8", "Airport surveillance video shows the lights came on for this landing, while Truck one and the group were stopped, about three hundred feet from the runway hold line. They stayed on until about the time Truck one reached the edge of the runway, and went off about three seconds before the collision.", 0.88, 1.0, ("photo", "ph/fig9.png", P9)),
 ("r9", "Truck one had a situational awareness tablet that showed the truck, other vehicles and aircraft, and could give visual and aural alerts when the truck approached a runway. It could not detect or warn of an impending collision. The report does not say what it displayed.", 0.88, 1.0, ("clip", "relay/m1f.mp4", 10.0, B1)),
 ("r10", "The report does not say what the truck's crew could see of those lights from the cab.", 1.12, 1.0, ("clip", "relay/m2f.mp4", 10.0, B2)),
 # ---- FAA response
 ("f1", "In May, the F A A announced sixteen and a half million dollars to put transponders on its own airport vehicles.", 0.88, 1.0, ("card", "faa")),
 ("f2", "About nineteen hundred vehicles, at forty-four airports with A S D E X and A S S C, and at two hundred twenty airports that have or will get surface awareness systems. The F A A said it had been planning the project for several months, and accelerated it after the LaGuardia accident.", 0.88, 1.0, ("card", "faa")),
 ("f3", "Vehicles without a transponder, the F A A explains, show up on controllers' screens only as blue diamonds, with no identity. The agency also reminded airports they can use federal grant money for the same equipment. More than fifty had already shown interest.", 0.88, 1.0, ("card", "faa")),
 ("f4", "Those are F A A actions. The N T S B lists its own investigation as ongoing, and its report as preliminary.", 1.12, 1.0, ("card", "faa")),
 # ---- open questions
 ("q1", "What do we still not know? One: the tower's part of the story. The report says who was on position and what was transmitted. It does not analyze it. An air traffic control group is part of the investigation. Nothing is concluded.", 0.88, 1.0, ("clip", "relay/br1.mp4", 24.0, BR)),
 ("q2", "Two: the truck's side. The report gives the radio calls, the lights, and interviews with the truck's crew, and does not analyze them. Airport operations and firefighting is one of the investigative groups.", 0.88, 1.0, ("clip", "relay/m2g.mp4", 30.0, B2)),
 ("q3", "Three: the airplane. The recorders were recovered and downloaded, a group was formed to transcribe the cockpit audio, and the report does not analyze what they show.", 0.88, 1.0, ("clip", "relay/br1.mp4", 45.0, BR)),
 ("q4", "Four: what the truck's own data recorder, engine control module and situational display show. The board retained them for later download.", 0.88, 1.0, ("clip", "relay/m2h.mp4", 40.0, B2)),
 ("q5", "The preliminary report contains no analysis and no probable cause, and its information is subject to change. A cause, if the board determines one, comes only at the end of the investigation.", 1.12, 1.0, ("clip", "relay/br2.mp4", 60.0, BR)),
 # ---- replay / end
 ("y1", "Replay. Eleven thirty-seven oh four: the tower instructs the truck to cross. Eleven thirty-seven seventeen: the jet touches down. Eleven thirty-seven twenty-two: the nose wheel, and the truck entering the runway. Then the flight recorder data ends.", 0.64, 0.97, ("3d", "replay")),
 ("y2", "The N T S B has not determined the cause of this accident. When it does, we will cover it. Every accident leaves a record.", 0.8, 0.97, ("card", "status")),
]
